function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 2000) return 'nums needs 1 to 2000 values.';
  for (let i = 0; i < nums.length; i++) {
    if (!Number.isInteger(nums[i]) || nums[i] < -2000 || nums[i] > 2000) return 'Each value is an integer between -2000 and 2000.';
    if (i > 0 && nums[i] < nums[i - 1]) return 'nums must be sorted in non-decreasing order.';
  }
  return null;
}

