function maximumCount(nums) {
  const firstAtLeast = (value) => {
    let left = 0;
    let right = nums.length;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (nums[mid] < value) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  };

  const negatives = firstAtLeast(0);
  const positives = nums.length - firstAtLeast(1);
  return Math.max(negatives, positives);
}

