function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const span = size === 'large' ? 2000 : [1, 3, 10][Math.floor(rand() * 3)];
  const shape = rand();
  let lo = -span;
  let hi = span;
  if (shape < 0.15) hi = 0;
  else if (shape < 0.3) lo = 0;
  else if (shape < 0.4) { lo = 0; hi = 0; }
  const nums = Array.from({ length: n }, () => lo + Math.floor(rand() * (hi - lo + 1)));
  nums.sort((a, b) => a - b);
  return [nums];
}
